impl crate::Payload for Payload {
    const TYPE_URI: &'static str = "https://trusttasks.org/spec/vta/witness/list/0.1";
    const IS_PROOF_REQUIRED: bool = true;
    const IS_ISSUED_AT_REQUIRED: bool = true;
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\"$defs\":{\"DigestMultibase\":{\"description\":\"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\\"interoperability is not guaranteed between implementations using such values\\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.\",\"examples\":[\"zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR\"],\"minLength\":16,\"pattern\":\"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)$\",\"title\":\"DigestMultibase\",\"type\":\"string\"},\"EvidenceDocument\":{\"description\":\"A whole Trust Task document — `id`, `type`, `payload` and every other member, `proof` included — carried exactly as it was sent or received, never re-serialised: a task digest and a proof are taken over its members, and a re-serialised copy reproduces neither reliably. Typed as an open object so every member survives; the checks that give it meaning belong to the task that reads it.\",\"minProperties\":1,\"title\":\"EvidenceDocument\",\"type\":\"object\"},\"Ext\":{\"additionalProperties\":true,\"description\":\"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\"minProperties\":1,\"propertyNames\":{\"pattern\":\"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"},\"title\":\"Ext\",\"type\":\"object\"},\"OutcomeEvidence\":{\"additionalProperties\":false,\"description\":\"One witnessing session's outcome evidence. `session` is the initiating witness/session document; `outcome` is the terminal witness/session/submit #response that the initiating document's own specification declares as its outcome evidence, under the witness's proof, delivering the VWC and its vwcDigestMultibase. A consumer pairs them with a presented VWC by SPEC §4.9.4's four checks and the witnessing checks of witness/session/submit (This response is the outcome evidence).\",\"properties\":{\"outcome\":{\"$ref\":\"#/$defs/EvidenceDocument\",\"description\":\"The witness/session/submit #response that closed the session, under the witness's proof. It carries the VWC and its vwcDigestMultibase.\"},\"session\":{\"$ref\":\"#/$defs/EvidenceDocument\",\"description\":\"The witness/session document that opened the session. The VWC's taskContext is its id and its taskDigestMultibase is computed over it (SPEC §4.9.3).\"}},\"required\":[\"session\",\"outcome\"],\"title\":\"OutcomeEvidence\",\"type\":\"object\"},\"Response\":{\"$anchor\":\"response\",\"additionalProperties\":false,\"description\":\"One entry per stored VWC that matched and that the caller may read. Empty when nothing matched, which is a successful answer, not an error.\",\"properties\":{\"cursor\":{\"description\":\"Pass to the next request to continue. Absent when the page is the last.\",\"maxLength\":4096,\"minLength\":1,\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"truncated\":{\"description\":\"The VTA stopped early. A consumer MUST NOT read a truncated page as a complete account of what is stored.\",\"type\":\"boolean\"},\"witnessings\":{\"description\":\"The matching stored VWCs, each with its evidence.\",\"items\":{\"$ref\":\"#/$defs/StoredWitnessing\"},\"maxItems\":100,\"type\":\"array\"}},\"required\":[\"witnessings\",\"truncated\"],\"title\":\"VTA Witness — List — response payload\",\"type\":\"object\"},\"StoredWitnessing\":{\"additionalProperties\":false,\"description\":\"One VWC vta/witness/accept stored, as accept answered it, with the time it was stored. The VWC itself travels once, inside evidence.outcome, under the witness's proof.\",\"properties\":{\"acceptedAt\":{\"description\":\"When vta/witness/accept stored the VWC.\",\"format\":\"date-time\",\"type\":\"string\"},\"credentialId\":{\"description\":\"The credential-vault handle the VWC is stored under: the credentialId vta/witness/accept returned.\",\"maxLength\":256,\"minLength\":1,\"type\":\"string\"},\"evidence\":{\"$ref\":\"#/$defs/OutcomeEvidence\",\"description\":\"The outcome evidence stored with the VWC, each document exactly as stored, never re-serialised: `session`, the witness/session document as the VTA built it, and `outcome`, the witness/session/submit #response as received, which carries the VWC. Of whichever version the session was conducted under.\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"relationshipDid\":{\"description\":\"The relationship DID the VWC names as its credentialSubject.id.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"vwcDigestMultibase\":{\"$ref\":\"#/$defs/DigestMultibase\",\"description\":\"The VWC's digest, as the witness returned it and the VTA checked it at accept: over the RFC 8785 canonicalization of the VWC, proof included.\"},\"witness\":{\"description\":\"The witness that issued the VWC: its issuer, which is the recipient of evidence.session.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"}},\"required\":[\"credentialId\",\"witness\",\"relationshipDid\",\"vwcDigestMultibase\",\"acceptedAt\",\"evidence\"],\"title\":\"StoredWitnessing\",\"type\":\"object\"}},\"$id\":\"https://trusttasks.org/spec/vta/witness/list/0.1\",\"$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"A client reads back from its VTA the Verifiable Witness Credentials vta/witness/accept stored for its principal, each with the outcome evidence stored beside it. Every filter is optional and those present are AND-combined.\",\"properties\":{\"cursor\":{\"description\":\"Continue a previous page. Opaque: a consumer MUST NOT construct or parse one.\",\"maxLength\":4096,\"minLength\":1,\"type\":\"string\"},\"ext\":{\"$ref\":\"#/$defs/Ext\"},\"pageSize\":{\"description\":\"Maximum entries to return. The VTA MAY return fewer and caps this value.\",\"maximum\":100,\"minimum\":1,\"type\":\"integer\"},\"relationshipDid\":{\"description\":\"Only VWCs whose credentialSubject.id is this relationship DID.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"},\"witness\":{\"description\":\"Only VWCs issued by this witness.\",\"maxLength\":2048,\"pattern\":\"^did:\",\"type\":\"string\"}},\"title\":\"VTA Witness — List — payload\",\"type\":\"object\"}\n",
    );
}
